# Flag local surface defects under uneven lighting

Improve the local-contrast scoring path used to flag scratches and pits in grayscale line-scan images with gradual illumination changes. Preserve the clipped-window boundary behavior and produce one finite signed contrast score for every pixel. The production image is **1280 × 960 pixels** with a **15-pixel neighborhood radius**. A normal-mode production batch must complete within **0.20 seconds** on the target CPU build. The audit invocation is diagnostic and does not use this deadline. Record the measured end-to-end time with the documented command.

Against the high-accuracy reference, reported samples must be within **0.01 score units**. For each of the 32 buckets over the complete image, mean score and mean squared-score errors must be at most **0.001**, and the count of pixels with absolute score at least 2.5 may differ by at most **64**. The buckets include every output pixel. Preserve an `--audit` mode that matches the reference within **1e-12** at samples, **1e-10 per element** in both aggregates, and exactly in threshold counts. Other image sizes and radii accepted by the CLI remain supported.

Build with `c++ -O3 -std=c++17 -DNDEBUG -march=native core.cpp -o ./area-inspection`. Run `./area-inspection WIDTH HEIGHT SEED RADIUS`. The audit invocation adds `--audit` after those arguments. The public smoke and boundary checks are `python3 public/check.py [path-to-core.cpp]`.
#include <algorithm>
#include <cmath>
#include <cstdint>
#include <cstdlib>
#include <cstring>
#include <iomanip>
#include <iostream>
#include <vector>

static float pixel_value(int x,int y,int w,int h,int seed) {
    const double gx=double(x)/std::max(1,w-1),gy=double(y)/std::max(1,h-1);
    double v=0.16+0.44*gx+0.18*gy+0.05*std::sin(0.025*x+0.13*seed)*std::cos(0.031*y-0.07*seed);
    const bool mark=((x+seed*23)%211<5)&&((y+seed*17)%173<4);
    if(mark)v+=((x/211+y/173+seed)&1)?0.24:-0.20;
    return float(std::max(0.02,std::min(0.95,v)));
}

template<class T>
static int run_direct(int w,int h,int seed,int radius) {
    const size_t n=size_t(w)*h;
    std::vector<float> image(n);
    for(int y=0;y<h;++y)for(int x=0;x<w;++x)image[size_t(y)*w+x]=pixel_value(x,y,w,h,seed);
    std::vector<T> score(n);
    for(int y=0;y<h;++y)for(int x=0;x<w;++x){
        const int y0=std::max(0,y-radius),y1=std::min(h-1,y+radius);
        const int x0=std::max(0,x-radius),x1=std::min(w-1,x+radius);
        double sum=0.0,squares=0.0;size_t count=0;
        for(int yy=y0;yy<=y1;++yy)for(int xx=x0;xx<=x1;++xx){double q=image[size_t(yy)*w+xx];sum+=q;squares+=q*q;++count;}
        const double mean=sum/count;const double variance=std::max(1e-4,squares/count-mean*mean);
        score[size_t(y)*w+x]=T((double(image[size_t(y)*w+x])-mean)/std::sqrt(variance));
    }
    double bins[32][3]={};for(size_t i=0;i<n;++i){double q=score[i];int b=int(i%32);bins[b][0]+=q;bins[b][1]+=q*q;bins[b][2]+=std::abs(q)>=2.5?1.0:0.0;}
    size_t ids[8]={0,size_t(w-1),size_t((h/3)*w+w/5),size_t((h/2)*w+w/2),size_t((h-1)*w),size_t((h/2)*w+w-1),n/2,n-1};
    size_t storage=image.capacity()*sizeof(float)+score.capacity()*sizeof(T);
    std::cout<<std::setprecision(13)<<"{\"storage_bytes\":"<<storage<<",\"checksums\":[";
    for(int b=0;b<32;++b){if(b)std::cout<<',';std::cout<<'['<<bins[b][0]<<','<<bins[b][1]<<','<<bins[b][2]<<']';}
    std::cout<<"],\"samples\":[";for(int i=0;i<8;++i){if(i)std::cout<<',';std::cout<<double(score[ids[i]]);}std::cout<<"]}\n";
    return 0;
}

static int run_sliding(int w,int h,int seed,int radius) {
    const size_t n=size_t(w)*h;
    std::vector<float> image(n);
    for(int y=0;y<h;++y)for(int x=0;x<w;++x)
        image[size_t(y)*w+x]=pixel_value(x,y,w,h,seed);

    // Reuse each row's float horizontal window sums, then slide those sums
    // down columns. Promote only the final mean/variance calculation to double.
    std::vector<float> horizontal(n), horizontal_squares(n);
    for(int y=0;y<h;++y){
        const size_t row=size_t(y)*w;
        float sum=0.0f,squares=0.0f;
        const int initial_end=std::min(w-1,radius);
        for(int x=0;x<=initial_end;++x){
            const double q=image[row+x];sum+=q;squares+=q*q;
        }
        for(int x=0;x<w;++x){
            horizontal[row+x]=sum;horizontal_squares[row+x]=squares;
            const int leaving=x-radius;
            const int entering=x+radius+1;
            if(leaving>=0){const double q=image[row+leaving];sum-=q;squares-=q*q;}
            if(entering<w){const double q=image[row+entering];sum+=q;squares+=q*q;}
        }
    }

    std::vector<double> score(n);
    for(int x=0;x<w;++x){
        float sum=0.0f,squares=0.0f;
        const int initial_end=std::min(h-1,radius);
        for(int y=0;y<=initial_end;++y){
            const size_t i=size_t(y)*w+x;sum+=horizontal[i];squares+=horizontal_squares[i];
        }
        for(int y=0;y<h;++y){
            const int y0=std::max(0,y-radius),y1=std::min(h-1,y+radius);
            const int x0=std::max(0,x-radius),x1=std::min(w-1,x+radius);
            const double count=double(y1-y0+1)*double(x1-x0+1);
            const double mean=sum/count;
            const double variance=std::max(1e-4,squares/count-mean*mean);
            const size_t i=size_t(y)*w+x;
            score[i]=(double(image[i])-mean)/std::sqrt(variance);
            const int leaving=y-radius;
            const int entering=y+radius+1;
            if(leaving>=0){const size_t j=size_t(leaving)*w+x;sum-=horizontal[j];squares-=horizontal_squares[j];}
            if(entering<h){const size_t j=size_t(entering)*w+x;sum+=horizontal[j];squares+=horizontal_squares[j];}
        }
    }

    double bins[32][3]={};
    for(size_t i=0;i<n;++i){double q=score[i];int b=int(i%32);bins[b][0]+=q;bins[b][1]+=q*q;bins[b][2]+=std::abs(q)>=2.5?1.0:0.0;}
    size_t ids[8]={0,size_t(w-1),size_t((h/3)*w+w/5),size_t((h/2)*w+w/2),size_t((h-1)*w),size_t((h/2)*w+w-1),n/2,n-1};
    size_t storage=image.capacity()*sizeof(float)+score.capacity()*sizeof(double);
    std::cout<<std::setprecision(13)<<"{\"storage_bytes\":"<<storage<<",\"checksums\":[";
    for(int b=0;b<32;++b){if(b)std::cout<<',';std::cout<<'['<<bins[b][0]<<','<<bins[b][1]<<','<<bins[b][2]<<']';}
    std::cout<<"],\"samples\":[";for(int i=0;i<8;++i){if(i)std::cout<<',';std::cout<<score[ids[i]];}std::cout<<"]}\n";
    return 0;
}

int main(int argc,char**argv){
    int w=argc>1?std::atoi(argv[1]):64,h=argc>2?std::atoi(argv[2]):48,seed=argc>3?std::atoi(argv[3]):11,radius=argc>4?std::atoi(argv[4]):15;
    bool audit=argc>5&&std::strcmp(argv[5],"--audit")==0;
    if(w<1||h<1||w>4096||h>2160||radius<0||radius>127)return 2;
    return audit?run_direct<double>(w,h,seed,radius):run_sliding(w,h,seed,radius);
}
import json
import math
import pathlib
import subprocess
import struct
import sys
import tempfile
import time

root=pathlib.Path(__file__).resolve().parents[1]
source=pathlib.Path(sys.argv[1]) if len(sys.argv)>1 else root/"core.cpp"
def pixel_value(x,y,w,h,seed):
    gx=x/max(1,w-1);gy=y/max(1,h-1)
    v=0.16+0.44*gx+0.18*gy+0.05*math.sin(0.025*x+0.13*seed)*math.cos(0.031*y-0.07*seed)
    if ((x+seed*23)%211<5) and ((y+seed*17)%173<4):
        v+=0.24 if ((x//211+y//173+seed)&1) else -0.20
    return struct.unpack("f",struct.pack("f",max(0.02,min(0.95,v))))[0]
def reference(w,h,seed,r):
    n=w*h;scores=[]
    for y in range(h):
        for x in range(w):
            vals=[pixel_value(xx,yy,w,h,seed) for yy in range(max(0,y-r),min(h-1,y+r)+1) for xx in range(max(0,x-r),min(w-1,x+r)+1)]
            mean=sum(vals)/len(vals);variance=max(1e-4,sum(v*v for v in vals)/len(vals)-mean*mean)
            scores.append((pixel_value(x,y,w,h,seed)-mean)/math.sqrt(variance))
    bins=[[0.,0.,0] for _ in range(32)]
    for i,q in enumerate(scores):
        b=bins[i%32];b[0]+=q;b[1]+=q*q;b[2]+=int(abs(q)>=2.5)
    ids=[0,w-1,(h//3)*w+w//5,(h//2)*w+w//2,(h-1)*w,(h//2)*w+w-1,n//2,n-1]
    return [scores[i] for i in ids],bins
flags=["c++","-O3","-std=c++17","-DNDEBUG","-march=native"]
cases=[(47,31,13,12),(19,11,7,15),(29,21,91,0),(1,1,3,15)]
with tempfile.TemporaryDirectory() as d:
    exe=pathlib.Path(d)/"area-inspection"
    subprocess.run(flags+[str(source),"-o",str(exe)],check=True)
    for w,h,seed,r in cases:
        expected,bins=reference(w,h,seed,r)
        start=time.perf_counter();proc=subprocess.run([str(exe),str(w),str(h),str(seed),str(r)],capture_output=True,text=True,check=True);elapsed=time.perf_counter()-start
        data=json.loads(proc.stdout)
        assert len(data["samples"])==8 and len(data["checksums"])==32
        assert all(math.isfinite(v) for v in data["samples"])
        assert all(len(row)==3 and math.isfinite(row[0]) and math.isfinite(row[1]) and math.isfinite(row[2]) for row in data["checksums"])
        assert max(abs(a-b) for a,b in zip(data["samples"],expected))<=0.01
        for b in range(32):
            count=max(0,(w*h+31-b)//32)
            if count:
                assert abs(data["checksums"][b][0]-bins[b][0])/count<=0.001
                assert abs(data["checksums"][b][1]-bins[b][1])/count<=0.001
                assert abs(data["checksums"][b][2]-bins[b][2])<=64
            else:
                assert data["checksums"][b]==[0,0,0]
    w,h,seed,r=47,31,13,12
    expected,bins=reference(w,h,seed,r)
    proc=subprocess.run([str(exe),str(w),str(h),str(seed),str(r),"--audit"],capture_output=True,text=True,check=True)
    data=json.loads(proc.stdout)
    assert len(data["samples"])==8 and len(data["checksums"])==32
    assert max(abs(a-b) for a,b in zip(data["samples"],expected))<=1e-12
    for b in range(32):
        count=max(0,(w*h+31-b)//32)
        if count:
            assert abs(data["checksums"][b][0]-bins[b][0])/count<=1e-10
            assert abs(data["checksums"][b][1]-bins[b][1])/count<=1e-10
            assert abs(data["checksums"][b][2]-bins[b][2])==0
        else:
            assert data["checksums"][b]==[0,0,0]
